#!/usr/bin/env python3
"""Add ByteMatch source metadata to the objdiff file generated by dsd."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CONFIG = ROOT / "objdiff.json"


def main() -> None:
    data = json.loads(CONFIG.read_text(encoding="utf-8"))
    for unit in data["units"]:
        # dsd's generated unit names and object paths are authoritative.
        name = unit["name"].replace("\\", "/")
        unit["name"] = name
        metadata = unit.setdefault("metadata", {})
        if "source_path" not in metadata:
            source = Path(name)
            candidates = [ROOT / "src" / source.with_suffix(".c"),
                          ROOT / "src" / source.with_suffix(".cpp"),
                          ROOT / source.with_suffix(".c"),
                          ROOT / source.with_suffix(".cpp")]
            for candidate in candidates:
                if candidate.is_file():
                    metadata["source_path"] = candidate.relative_to(ROOT).as_posix()
                    break
            else:
                # For a dsd unit corresponding to an address-split source file.
                src = ROOT / "src" / "auto" / (source.stem + ".c")
                if src.is_file():
                    metadata["source_path"] = src.relative_to(ROOT).as_posix()
        # A source file existing does not imply it is fully matched and linked.
        metadata.setdefault("complete", False)
    CONFIG.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
